css:
.card {
  width: 105px;
  height: 105px;
  background: linear-gradient(
    136deg,
    rgba(39, 79, 37, 1) 60%,
    rgba(76, 155, 95, 1) 92%
  );
  border: 2px solid #043918;
  text-align: center;
}
.text {
  color: #fcfeff;
  margin-top: 20px;
  font-size: 40px;
  font-weight: 600;
}
.text sup {
  font-size: 20px;
}
.text2 {
  font-family: Georgia, serif;
  font-weight: 900;
  color: #184f3b;
  font-size: 32px;
  padding: 5px;
}
